def _to_bioimage(x):
    
    cls = BioImage if x.shape[0] == 1 else BioMultiChannel

    if isinstance(x, (MetaTensor, torchTensor)):
        return cls.from_metatensor(x)

    if isinstance(x, np.ndarray):
        return cls.from_numpy(x)

    return x

