@typedispatch
def show_batch(
    x: list[np.ndarray],
    y: list,
    samples=None,
    ctxs=None,
    max_n=9,
    nrows=None,
    ncols=None,
    figsize=None,
    vocab=None,
    **kwargs,
):
    if samples is None:
        x = x[:max_n]

        x_bio = [_to_bioimage(t) for t in x]

        y_list = []
        for value in y[:len(x)]:
            if isinstance(value, np.generic):
                value = value.item()
            elif isinstance(value, np.ndarray) and value.ndim == 0:
                value = value.item()

            y_list.append(value)

        if vocab is not None:
            y_list = [vocab[o] for o in y_list]

        samples = list(zip(x_bio, y_list))

    if ctxs is None:
        ctxs = get_grid(
            min(len(samples), max_n),
            nrows=nrows,
            ncols=ncols,
            figsize=figsize,
        )

    if isinstance(ctxs, np.ndarray):
        ctxs = ctxs.flatten()

    for i, ((img, lbl), ax) in enumerate(zip(samples, ctxs)):
        if i >= max_n:
            break

        img.show(ctx=ax, **kwargs)
        ax.set_title(str(lbl), fontsize=10)

    return ctxs

